{
  "description": "Inject planning guidelines when a session reaches plan mode, attach delegation guidance once a plan grows large and a warning once it passes the gate's limit, gate plan re-presents, and show a plan's size against that limit",
  "modules": ["../mod/register.ts"],
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "ExitPlanMode",
        "hooks": [
          {
            "type": "command",
            "command": "bun \"${CLAUDE_PLUGIN_ROOT}/hooks/gate.ts\""
          }
        ]
      }
    ]
  }
}

